package top.aameow.management.mapper;
import java.util.*;
import org.apache.ibatis.annotations.*;
public interface WorkProjectMapper {
 String COLUMNS="p.id,p.project_type projectType,p.project_no projectNo,p.project_name projectName,p.contract_id contractId,c.contract_name contractName,c.contract_id contractNumber,p.client_name clientName,p.site_address siteAddress,p.contact_name contactName,p.contact_phone contactPhone,p.leader_user_id leaderUserId,u.nick_name leaderName,p.technical_user_id technicalUserId,t.nick_name technicalName,date_format(p.start_date,'%Y-%m-%d') startDate,date_format(p.end_date,'%Y-%m-%d') endDate,p.number_pending numberPending,p.classification_pending classificationPending,p.legacy_number legacyNumber,p.version,p.created_by createdBy,p.updated_by updatedBy,p.created_at createdAt,p.updated_at updatedAt";
 String FROM=" from zj_work_project p left join zj_contract c on c.id=p.contract_id left join sys_user u on u.user_id=p.leader_user_id left join sys_user t on t.user_id=p.technical_user_id ";
 @Select("<script>select "+COLUMNS+FROM+"<where><if test='projectType != null and projectType != &quot;&quot;'>and p.project_type=#{projectType}</if><if test='name != null and name != &quot;&quot;'>and (p.project_name like concat('%',#{name},'%') or p.project_no like concat('%',#{name},'%'))</if><if test='pending != null and pending == &quot;1&quot;'>and p.contract_id is null</if></where> order by p.id desc</script>") List<Map<String,Object>> list(Map<String,Object> q);
 @Select("select "+COLUMNS+",p.details_json detailsJson,p.registration_json registrationJson,p.remark"+FROM+"where p.id=#{id}") Map<String,Object> get(Long id);
 @Select("select id,contract_type projectType from zj_contract_identity where id=#{id}") Map<String,Object> contract(Long id);
 @Select("select user_id from sys_user where user_id=#{id} and status='0' and del_flag='0'") Long user(Long id);
 @Select("select id,contract_id contractNo,contract_name contractName,contract_file contractFile from zj_contract where contract_type=#{projectType} and (contract_name like concat('%',#{name},'%') or contract_id like concat('%',#{name},'%')) order by id desc") List<Map<String,Object>> contracts(Map<String,Object> q);
 @Select("select user_id id,nick_name name,user_name username from sys_user where status='0' and del_flag='0' and (nick_name like concat('%',#{name},'%') or user_name like concat('%',#{name},'%')) order by user_id") List<Map<String,Object>> users(String name);
 @Insert("insert into zj_work_project_sequence(number_year,project_type,sequence_value) values(#{year},#{type},0) on duplicate key update sequence_value=sequence_value") int ensureSequence(@Param("year") int year,@Param("type") String type);
 @Select("select sequence_value from zj_work_project_sequence where number_year=#{year} and project_type=#{type} for update") Long lockSequence(@Param("year") int year,@Param("type") String type);
 @Update("update zj_work_project_sequence set sequence_value=#{value} where number_year=#{year} and project_type=#{type}") int sequence(@Param("year") int year,@Param("type") String type,@Param("value") Long value);
 @Select("select count(*) from zj_work_project_number where project_no=#{code}") int reserved(String code);
 @Insert("insert into zj_work_project_number(project_no,project_id) values(#{code},#{id})") int reserve(@Param("code") String code,@Param("id") Long id);
 @Update("update zj_work_project set project_no=#{code},number_pending=0,version=version+1,updated_by=#{actor},updated_at=now() where id=#{id} and number_pending=1 and version=#{version}") int replaceNumber(@Param("id") Long id,@Param("version") Long version,@Param("code") String code,@Param("actor") String actor);
 @Insert("insert into zj_work_project(project_type,project_no,project_name,contract_id,client_name,site_address,contact_name,contact_phone,leader_user_id,technical_user_id,start_date,end_date,created_by,updated_by) values(#{projectType},#{projectNo},#{projectName},#{contractId},#{clientName},#{siteAddress},#{contactName},#{contactPhone},#{leaderUserId},#{technicalUserId},#{startDate},#{endDate},#{actor},#{actor})") @Options(useGeneratedKeys=true,keyProperty="id") int add(Map<String,Object> v);
 @Update("<script>update zj_work_project <set><choose><when test='section == &quot;basic&quot;'>project_name=#{projectName},project_type=#{projectType},classification_pending=#{classificationPending},contract_id=#{contractId},client_name=#{clientName},site_address=#{siteAddress},contact_name=#{contactName},contact_phone=#{contactPhone},leader_user_id=#{leaderUserId},technical_user_id=#{technicalUserId},start_date=#{startDate},end_date=#{endDate},</when><when test='section == &quot;details&quot;'>details_json=#{detailsJson},</when><when test='section == &quot;registration&quot;'>registration_json=#{registrationJson},</when><when test='section == &quot;notes&quot;'>remark=#{remark},</when></choose>version=version+1,updated_by=#{actor},updated_at=now()</set>where id=#{id} and version=#{version}</script>") int section(Map<String,Object> v);
 @Select("select id,title,description,severity,status,date_format(found_date,'%Y-%m-%d') foundDate,date_format(resolved_date,'%Y-%m-%d') resolvedDate,files,created_by createdBy,created_at createdAt from zj_work_project_issue where project_id=#{id} order by id desc") List<Map<String,Object>> issues(Long id);
 @Insert("insert into zj_work_project_issue(project_id,title,description,severity,status,found_date,resolved_date,files,created_by) values(#{projectId},#{title},#{description},#{severity},#{status},#{foundDate},#{resolvedDate},#{files},#{actor})") @Options(useGeneratedKeys=true,keyProperty="id") int addIssue(Map<String,Object> v);
 @Update("update zj_work_project_issue set title=#{title},description=#{description},severity=#{severity},status=#{status},found_date=#{foundDate},resolved_date=#{resolvedDate},files=#{files},updated_at=now() where id=#{id} and project_id=#{projectId}") int editIssue(Map<String,Object> v);
 @Delete("delete from zj_work_project_issue where id=#{id} and project_id=#{projectId}") int removeIssue(@Param("projectId") Long project,@Param("id") Long id);
 @Select("select id,title,plan_type planType,date_format(start_date,'%Y-%m-%d') startDate,date_format(end_date,'%Y-%m-%d') endDate,status,assignee_id assigneeId,remark,created_by createdBy from zj_work_project_plan where project_id=#{id} order by start_date,id") List<Map<String,Object>> plans(Long id);
 @Insert("insert into zj_work_project_plan(project_id,title,plan_type,start_date,end_date,status,assignee_id,remark,created_by) values(#{projectId},#{title},#{planType},#{startDate},#{endDate},#{status},#{assigneeId},#{remark},#{actor})") @Options(useGeneratedKeys=true,keyProperty="id") int addPlan(Map<String,Object> v);
 @Update("update zj_work_project_plan set title=#{title},plan_type=#{planType},start_date=#{startDate},end_date=#{endDate},status=#{status},assignee_id=#{assigneeId},remark=#{remark},updated_at=now() where id=#{id} and project_id=#{projectId}") int editPlan(Map<String,Object> v);
 @Delete("delete from zj_work_project_plan where id=#{id} and project_id=#{projectId}") int removePlan(@Param("projectId") Long project,@Param("id") Long id);
 @Select("select snapshot_json snapshotJson from zj_work_project_legacy where project_id=#{id} and source_table='zj_project_cost'") List<Map<String,Object>> expenseLegacy(Long id);
}
